<?php
session_start(); require_once __DIR__.'/includes/config.php';
if (empty($_SESSION['alogin']) || empty($_SESSION['uid'])) { header('Location: index.php'); exit; }
function h($v){return htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');}
$sql="SELECT x.*, a.codigo_inventario, COALESCE(a.descripcion, c.nombre) AS activo,
 p.nombres AS persona, u.nombre AS ubicacion, s.nombre AS sede,
 (SELECT GROUP_CONCAT(CONCAT(au.ubicacion_espacio, IF(au.area_departamento IS NULL OR au.area_departamento='', '', CONCAT(' — ',au.area_departamento))) SEPARATOR '; ') FROM asignacion_areas_usuarias au WHERE au.asignacion_id=x.id) AS areas_compartidas
 FROM asignaciones x INNER JOIN activos a ON a.id=x.activo_id INNER JOIN categorias_activos c ON c.id=a.categoria_id
 LEFT JOIN personas p ON p.id=x.persona_id LEFT JOIN ubicaciones u ON u.id=a.ubicacion_id LEFT JOIN sedes s ON s.id=u.sede_id
 ORDER BY x.fecha_creacion DESC, x.id DESC";
try{$rows=$dbh->query($sql)->fetchAll(PDO::FETCH_ASSOC);}catch(PDOException $e){error_log($e->getMessage());$rows=array();$error='No fue posible consultar las asignaciones. Verifica que hayas ejecutado la actualización SQL del módulo.';}
?>
