<div class="clearfix" style="margin-bottom:15px"><a href="add-asignacion.php" class="btn btn-primary pull-right"><i class="fa fa-plus"></i> Agregar asignación</a></div><div class="table-responsive"><table id="example" class="display table table-striped table-bordered" cellspacing="0" width="100%"><thead><tr><th>N.º control</th><th>Código inventario</th><th>Activo</th><th>Modalidad</th><th>Persona receptora</th><th>Sede</th><th>Ubicación física</th><th>Áreas / oficinas usuarias</th><th>Fecha</th><th>Estado</th></tr></thead><tbody>
<?php foreach($rows as $r): ?><tr><td><?php echo h($r['numero_control']); ?></td><td><?php echo h($r['codigo_inventario']); ?></td><td><?php echo h($r['activo']); ?></td><td><?php echo $r['tipo_asignacion']==='PERSONA'?'Entrega a persona':'Uso compartido en sede'; ?></td><td><?php echo h($r['persona']?:'No aplica'); ?></td><td><?php echo h($r['sede']?:'—'); ?></td><td><?php echo h($r['ubicacion']?:'—'); ?></td><td><?php echo h($r['areas_compartidas']?:'—'); ?></td><td><?php echo h($r['fecha_asignacion']); ?></td><td><?php echo h($r['estado_asignacion']); ?></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="10" class="text-center">Todavía no hay asignaciones registradas.</td></tr><?php endif; ?>
</tbody></table></div></div></div></div></section></div></div></div><?php include __DIR__.'/includes/footer.php'; ?>
